import time
from dataclasses import dataclass
from typing import Any, Optional

@dataclass
class CacheEntry:
    key: str
    value: Any
    ttl_seconds: Optional[float]
    created_at: float

    def is_expired(self, current_time: float) -> bool:
        if self.ttl_seconds is None:
            return False
        return current_time - self.created_at >= self.ttl_seconds

import time
import threading
from collections import OrderedDict
from typing import Any, Optional
from .entry import CacheEntry

class LRUCache:
    def __init__(self, capacity: int, default_ttl: Optional[float] = None):
        if capacity <= 0:
            raise ValueError('Capacity must be positive')
        self.capacity = capacity
        self.default_ttl = default_ttl
        self._store: OrderedDict[str, CacheEntry] = OrderedDict()
        self._lock = threading.RLock()

    def _purge_expired(self, now: float) -> None:
        expired_keys = [
            key for key, entry in self._store.items()
            if entry.is_expired(now)
        ]
        for key in expired_keys:
            del self._store[key]

    def get(self, key: str) -> Optional[Any]:
        with self._lock:
            now = time.monotonic()
            if key not in self._store:
                return None
            entry = self._store[key]
            if entry.is_expired(now):
                del self._store[key]
                return None
            self._store.move_to_end(key)
            return entry.value

    def put(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        with self._lock:
            now = time.monotonic()
            effective_ttl = ttl if ttl is not None else self.default_ttl
            if key in self._store:
                existing = self._store[key]
                if existing.is_expired(now):
                    del self._store[key]
                else:
                    self._store.move_to_end(key)
            else:
                # Purge stale items before inserting a new one so that a full
                # cache can reclaim space from expired entries.
                expired_keys = [
                    k for k, e in self._store.items()
                    if e.is_expired(now)
                ]
                for k in expired_keys:
                    del self._store[k]
            self._store[key] = CacheEntry(key, value, effective_ttl, now)
            while len(self._store) > self.capacity:
                oldest_key, _oldest_entry = next(iter(self._store.items()))
                del self._store[oldest_key]
